    public void Music_Stop(int aFadeoutTime)
    {
        f_NextMusic.rFileName = "";
        switch (f_Music)
        {
            case mp_MIDI:
                mciSendString("close d2dmidi", null, 0, 0);
                DeleteFile(f_MusicMidiTempFile);
