    private void SoundSystemStart()
    {
        BASS_DEVICEINFO l_DevInfo = default;
        int I;
        TMidiOutCaps l_MidiOutCaps;
        string l_BassDLL;
    
        f_MidiDevice = ( - 1);
        for (I = 0; I <= (midiOutGetNumDevs - 1); I++)
        {
            MidiOutGetDevCaps(I, /* TODO: Delphi address-of */ l_MidiOutCaps, SizeOf(l_MidiOutCaps));
            if (l_MidiOutCaps.wTechnology == MOD_SWSYNTH)
            {
                f_MidiDevice = I;
                break;
            }
        }
        f_MusicVolume = 128;
        if (BASS_Handle != 0)
        {
            return;
        }
        l_BassDLL = (ExtractFilePath(ParamStr(0)) + "bass.dll");
        if (FileExists(l_BassDLL))
        {
            if (Load_BASSDLL(l_BassDLL))
            {
