                {
                    if (BASS_Init(( - 1), f_SoundSampleRate, 0, f_WHandle, null))
                    {
                        BASS_GetDeviceInfo(1, ref l_DevInfo);
                        System_Log("\r\nSound Device: %s", new object[] { global::System.Runtime.InteropServices.Marshal.PtrToStringAnsi(l_DevInfo.name) ?? string.Empty });
                        System_Log("Sample rate : %d\r\n", new object[] { f_SoundSampleRate });
                    }
                    else
                    {
                        System_Log("\r\nBASS init failed, so expect simplified (WAV and MIDI) sound\r\n");
                        Unload_BASSDLL();
                    }
                }
                else
                {
                    System_Log("\r\nIncorrect BASS.DLL version\r\n");
                    Unload_BASSDLL();
                }
            }
            else
            {
                System_Log("\r\nError loading BASS.DLL, so expect simplified (WAV and MIDI) sound\r\n");
            }
        }
        else
        {
            System_Log("\r\nBASS.DLL not found, so expect simplified (WAV and MIDI) sound\r\n");
        }
    }
    
