    public bool System_Start()
    {
        string l_Str = default!;
        TWndClass l_WndClass;
        int l_Width;
        int l_Height;
        HICON l_Icon;
        bool result;
    
        result = false;
        if (FileExists(f_LogFileName))
        {
            DeleteFile(f_LogFileName);
        }
        DateTimeToString(l_Str, "dddddd, tt", Now);
        System_Log("%s", new object[] { l_Str });
        System_Log("Delphi 2D engine starting...");
        System_Log("Engine version: %x.%x\r\n", new object[] { (D2DVersion >> 8), (D2DVersion & 0xFF) });
        f_Instance = SysInit.HInstance;
        l_WndClass();
        if (Windows.RegisterClass(l_WndClass) == 0)
        {
            System_Log("Can't register window class");
            return result;
        }
        l_Width = (f_ScreenWidth + (GetSystemMetrics(SM_CXFIXEDFRAME) * 2));
        l_Height = ((f_ScreenHeight + (GetSystemMetrics(SM_CYFIXEDFRAME) * 2)) + GetSystemMetrics(SM_CYCAPTION));
        f_RectW.Left = ((GetSystemMetrics(SM_CXSCREEN) - l_Width) / 2);
        f_RectW.Top = ((GetSystemMetrics(SM_CYSCREEN) - l_Height) / 2);
        f_RectW.Right = (f_RectW.Left + l_Width);
        f_RectW.Bottom = (f_RectW.Top + l_Height);
        f_WStyleW = ((((WS_POPUP | WS_CAPTION) | WS_SYSMENU) | WS_MINIMIZEBOX) | WS_VISIBLE);
        f_RectFS.Left = 0;
        f_RectFS.Top = 0;
        f_RectFS.Right = GetSystemMetrics(SM_CXSCREEN);
        f_RectFS.Bottom = GetSystemMetrics(SM_CYSCREEN);
        f_WStyleFS = (WS_POPUP | WS_VISIBLE);
        if (f_Windowed)
        {
            f_WHandle = CreateWindowEx(0, cWinClassName, PChar(f_WindowTitle), (uint)(f_WStyleW), f_RectW.left, f_RectW.top, (f_RectW.right - f_RectW.left), (f_RectW.bottom - f_RectW.top), 0, 0, f_Instance, null);
        }
        else
        {
            f_WHandle = CreateWindowEx(WS_EX_TOPMOST, cWinClassName, PChar(f_WindowTitle), (uint)(f_WStyleFS), 0, 0, 0, 0, 0, 0, f_Instance, null);
        }
        if (f_WHandle == 0)
        {
            System_Log("Can't create window...");
            return result;
        }
        ShowWindow(f_WHandle, SW_SHOW);
        l_Icon = LoadIcon(MainInstance, "MAINICON");
        SetClassLong(f_WHandle, GCL_HICON, l_Icon);
        SendMessage(f_WHandle, WM_SETICON, 1, l_Icon);
        timeBeginPeriod(1);
        Randomize();
        if (!GfxInit())
        {
            System_Shutdown();
            return result;
        }
        if (f_SoundOn)
        {
            SoundSystemStart();
        }
        System_Log("Init done.\r\n");
        f_FPS = 0;
        f_FPSCount = 0;
        f_Time = 0.0;
        f_FixedDelta = 0;
        f_Time0 = timeGetTime;
        f_Time0FPS = f_Time0;
        result = true;
        return result;
    }
    
    public void System_Log(in string aFormat, object[] Args)
    {
        System_Log(global::FireURQ.Runtime.D2dLogFormat.Format(aFormat, Args));
    }
    
