    public void System_Run()
    {
        TMsg l_Msg;
        TPoint l_Point = default!;
        TRect l_Rect = default!;
        bool l_Finish;
    
        if (f_WHandle == 0)
        {
            System_Log("Engine was not started!");
            return;
        }
        if (!(f_OnFrame != null))
        {
            System_Log("Frame function is not assigned!");
            return;
        }
        l_Finish = false;
        while (!l_Finish)
        {
            if (PeekMessage(l_Msg, 0, 0, 0, PM_REMOVE))
            {
                if (l_Msg.message == WM_QUIT)
                {
                    l_Finish = true;
                }
                DispatchMessage(l_Msg);
                continue;
            }
            GetCursorPos(l_Point);
            GetClientRect(f_WHandle, l_Rect);
            MapWindowPoints(f_WHandle, 0, l_Rect, 2);
            f_MouseOver = (f_MouseCaptured | (PtInRect(l_Rect, l_Point) & (WindowFromPoint(l_Point) == f_WHandle)));
            if (f_Active | f_DontSuspend)
            {
                do
                {
                    f_DeltaTicks = (timeGetTime - f_Time0);
                    if (f_DeltaTicks <= f_FixedDelta)
                    {
                        Sleep(1);
                    }
                }
                while (!((f_DeltaTicks > f_FixedDelta)));
                f_DeltaTime = (f_DeltaTicks / 1000.0);
                if (f_DeltaTime > 0.2)
                {
                    if (f_FixedDelta > 0)
                    {
                        f_DeltaTime = (f_FixedDelta / 1000.0);
                    }
                    else
                    {
                        f_DeltaTime = 0.01;
                    }
                }
                f_Time = (f_Time + f_DeltaTime);
                f_Time0 = timeGetTime;
                if ((f_Time0 - f_Time0FPS) < 1000)
                {
                    f_FPSCount++;
                }
                else
                {
                    f_FPS = f_FPSCount;
                    f_FPSCount = 0;
                    f_Time0FPS = f_Time0;
                }
                f_OnFrame(f_DeltaTime, l_Finish);
                if (f_OnRender != null)
                {
                    f_OnRender();
                }
            }
            else
            {
                Sleep(1);
            }
            CheckSynchronize();
        }
    }
    
    public void System_Shutdown()
    {
        System_Log("Finishing...");
        timeEndPeriod(1);
        ClearQueue();
        GfxDone();
        if (f_SoundOn)
        {
            SoundSystemStop();
        }
        if (f_WHandle != 0)
        {
            DestroyWindow(f_WHandle);
            f_WHandle = 0;
        }
        if (f_Instance != 0)
        {
            Windows.UnregisterClass(cWinClassName, f_Instance);
        }
        System_Log("The End.");
    }
    
